<?php $section=$section??'profile';$titles=['profile'=>'اطلاعات شخصی','security'=>'تنظیمات و امنیت','rules'=>'قوانین حساب','phone'=>'شماره همراه']; ?>
<div class="account-page account-detail"><a class="account-back" href="<?= $this->h($this->url('/account')) ?>"><?= $this->icon('arrow') ?> بازگشت به حساب من</a><header class="account-detail-heading"><span class="eyebrow">حساب مرشد</span><h1><?= $titles[$section] ?></h1><p class="muted">هر بخش را جداگانه مشاهده و مدیریت کن.</p></header><nav class="account-tabs" aria-label="بخش‌های تنظیمات حساب"><?php foreach(['profile'=>'اطلاعات شخصی','security'=>'امنیت','rules'=>'قوانین'] as $key=>$label): ?><a <?= $section===$key?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/account/'.$key)) ?>"><?= $label ?></a><?php endforeach; ?></nav>
<?php if($section==='profile'): ?><section class="card section avatar-editor"><h2>عکس حساب من</h2><?php if(!empty($this->actor['avatar_asset_id'])): ?><img class="personal-avatar" src="<?= $this->h($this->url('/content/asset?id='.$this->actor['avatar_asset_id'])) ?>" width="96" height="96" alt="عکس حساب شما"><?php endif; ?><?= str_replace('<form method="post"','<form enctype="multipart/form-data" method="post"',$this->start('/account/avatar')) ?><label for="personal-avatar">انتخاب عکس</label><input id="personal-avatar" type="file" name="attachment" accept="image/png,image/jpeg" required><p class="small muted">عکس در حساب شما ذخیره می‌شود و با ورود از دستگاه دیگر هم نمایش داده می‌شود.</p><button>ذخیرهٔ عکس</button></form><?php if(!empty($this->actor['avatar_asset_id'])): ?><?= $this->start('/account/avatar') ?><input type="hidden" name="remove" value="1"><button class="secondary">حذف عکس</button></form><?php endif; ?></section><section class="card"><h2>مشخصات من</h2><p>شماره تأییدشده: <bdi><?= $this->h($user['phone']??'ثبت نشده') ?></bdi></p><?= $this->start('/me/profile') ?><?php require __DIR__.'/profile-fields.php'; ?><button class="primary">ذخیره مشخصات</button></form></section>
<?php elseif($section==='security'): ?><section class="card"><h2><?= $user['has_password']?'تغییر رمز':'تنظیم رمز' ?></h2><?= $this->start('/me/password') ?><?php if($user['has_password']): ?><?= $this->field('current_password','رمز فعلی','password') ?><?php endif; ?><?= $this->field('new_password','رمز جدید، حداقل ۸ نویسه','password') ?><button class="primary">ذخیره رمز</button></form><p class="small muted">برای تنظیم اولین رمز، ورود تازه با یکی از روش‌های تأییدشدهٔ حساب لازم است.</p></section>
<section class="card account-security"><h2>امنیت حساب</h2><div class="account-method-summary"><span class="badge">شماره همراه: <?= $user['phone']?'تأیید شده':'ثبت نشده' ?></span><span class="badge">رمز عبور: <?= $user['has_password']?'فعال':'تنظیم نشده' ?></span></div><p class="muted small">ورود با شماره و رمز یا کد پیامکی برای استفاده از حساب کافی است. افزودن روش‌های دیگر اختیاری است.</p>
<details class="optional-connections"><summary>روش‌های اختیاری ورود: گوگل و ایتا</summary><div class="provider-methods"><?php foreach(['google'=>'گوگل','eitaa'=>'ایتا'] as $provider=>$label): $connected=in_array($provider,array_column($identities??[],'provider'),true); ?><div class="provider-method"><h3><?= $label ?> <span class="small muted"><?= $connected?'متصل':'افزوده نشده' ?></span></h3><div class="provider-actions"><?= $this->start('/auth/'.$provider.'/start') ?><input type="hidden" name="purpose" value="<?= $connected?'reauth':'link' ?>"><?php if($provider==='eitaa'): ?><input type="hidden" name="init_data" data-eitaa-input><?php endif; ?><button class="secondary" <?= (($this->config[$provider]['enabled']??false)&&($this->config[$provider]['live_verified']??false))?'':'disabled' ?>><?= $connected?'تأیید دوباره هویت':'افزودن ورود با '.$label ?></button></form><?php if($connected): ?><?= $this->start('/me/identities/unlink') ?><input type="hidden" name="provider" value="<?= $provider ?>"><button class="secondary">قطع اتصال</button></form><?php endif; ?></div></div><?php endforeach; ?></div><p class="small muted">تغییر روش ورود به تأیید تازهٔ هویت نیاز دارد. آخرین روش قابل استفاده حذف نمی‌شود.</p></details>
<section class="section"><h3>پیام‌های ایتا</h3><p class="small muted">مجوز دریافت پیام هنگام ثبت‌نام انتخاب می‌شود. کاربران قبلی می‌توانند از صفحهٔ اعلان‌ها آن را فعال کنند.</p><a class="secondary" href="<?= $this->h($this->url('/notifications')) ?>">اعلان‌ها و دریافت پیام ایتا</a></section><div class="account-tools"><a class="secondary" href="<?= $this->h($this->url('/account/sessions')) ?>">مدیریت دستگاه‌ها و نشست‌ها</a><a class="secondary" href="<?= $this->h($this->url('/notifications')) ?>">اعلان‌های حساب</a></div></section><?php elseif($section==='rules'): ?><section class="card section"><h2>قوانین پایه حساب</h2><?php if($legal): ?><p><?= $this->h($legal['title']) ?> — نسخه <?= $this->h($legal['version_no']) ?></p><div class="bodytext"><?= $this->h($legal['body']) ?></div><?php if($accepted): ?><p class="notice">این نسخه را پذیرفته‌اید.</p><?php else: ?><?= $this->start('/legal/accept') ?><input type="hidden" name="id" value="<?= $this->h($legal['id']) ?>"><label class="row"><input class="checkbox" type="checkbox" required>متن همین نسخه را خوانده‌ام و می‌پذیرم.</label><button class="primary">ثبت پذیرش این نسخه</button></form><?php endif; ?><?php else: ?><p class="muted">هنوز نسخه‌ای از قوانین پایه منتشر نشده است.</p><?php endif; ?><p class="notice section">ثبت درخواست فعال است؛ برگزاری تماس و چت و شرایط ضبط هنوز آماده نشده‌اند.</p></section>

<?php elseif($section==='phone'): ?><?php if(empty($user['phone'])&&in_array('eitaa',array_column($identities??[],'provider'),true)): ?><section class="card section"><h2>ادامه با حساب قبلی</h2><p>اگر پیش‌تر با شماره همراه ثبت نام کرده‌ای، اطلاعات حساب قبلی‌ات را با تأیید همان شماره بازیابی کن.</p><a class="primary" href="<?= $this->h($this->url('/account/identify')) ?>">پیداکردن حساب با شماره</a></section><?php endif; ?>
<?php if(empty($user['phone'])): ?><section class="card section"><h2>تأیید شماره همراه</h2><p>برای خدماتی که به شماره تأییدشده نیاز دارند، مالکیت شماره را جداگانه تأیید کن.</p><?= $this->start('/me/phone/request') ?><?= $this->field('phone','شماره همراه','tel') ?><?= $this->field('current_password','رمز فعلی حساب','password') ?><button>دریافت کد تأیید</button></form></section><?php endif; ?>
<?php endif; ?></div>
